  "name": "rf_set_vendor_cca_flags",
  "confidence": "medium",
  "docstring": "Applies a vendor CCA configuration byte array to radio MMIO registers and dispatches a SetVendorCca IPC/event.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "vendor_cca_flags",
    "v1": "flags0"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "vendor CCA byte controlling enable/status bits and upper-nibble condition"
    },
    {
      "offset": 1,
      "meaning": "low-byte field copied into bits 0-7 of first RF register"
    },
    {
      "offset": 2,
      "meaning": "low-byte field copied into bits 0-7 of second RF register"
    },
    {
      "offset": 3,
      "meaning": "nibble field copied into bits 12-15 of first RF register"
    },
    {
      "offset": 4,
      "meaning": "nibble field copied into bits 12-15 of second RF register"
    }
  ]
}
